use crate::{Key, ModSet};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum KeyState {
    Down,
    Up,
    /// Auto-repeat generated by the system while a key is held.
    Repeat,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct KeyEvent {
    pub key: Key,
    pub state: KeyState,
    /// Input event: the modifiers reported by the system (display only; the engine tracks modifier state itself).
    /// Output event: the modifiers that should be down when this event is posted.
    pub mods: ModSet,
}

impl KeyEvent {
    pub const fn new(key: Key, state: KeyState) -> Self {
        KeyEvent {
            key,
            state,
            mods: ModSet::empty(),
        }
    }
}
